update public.quiz_questions
set active = false
where active = true
  and (
    (category = 'razonamiento' and topic in ('Lectura critica', 'Razonamiento cuantitativo', 'Razonamiento cuantitativo y lectura critica'))
    or (category = 'pedagogica' and topic = 'Competencias comportamentales docentes')
  );

with base_sequence as (
  select coalesce(max(sequence), 0) + 1000 as value
  from public.quiz_questions
),
new_questions (
  position, external_id, test_id, test_title, category, block_id, block_range, topic, situation,
